 1 | // SPDX-License-Identifier: BUSL-1.1
 2 | pragma solidity ^0.8.0;
 3 | 
 4 | import "./LockeERC20.sol";
 5 | import "solmate/utils/SafeTransferLib.sol";
 6 | import "solmate/tokens/ERC20.sol";
 7 | 
 8 | // ====== Governance =====
 9 | contract Governed {
10 |     address public gov;
11 |     address private pendingGov;
12 |     address public emergency_gov;
13 | 
14 |     event NewGov(address indexed oldGov, address indexed newGov);
15 |     event NewPendingGov(address indexed oldPendingGov, address indexed newPendingGov);
16 | 
17 |     constructor(address _governor, address _emergency_governor) public {
18 |         gov = _governor;
19 |         emergency_gov = _emergency_governor;
20 |     }
21 | 
22 |     function governorship() public view returns (address, address, address) {
23 |         return (gov, emergency_gov, pendingGov);
24 |     }
25 | 
26 |     /// Update pending governor
27 |     function setPendingGov(address newPendingGov) governed public {
28 |         address old = pendingGov;
29 |         pendingGov = newPendingGov;
30 |         emit NewPendingGov(old, newPendingGov);
31 |     }
32 | 
33 |     /// Accepts governorship
34 |     function acceptGov() public {
35 |         require(pendingGov == msg.sender, "!pending");
36 |         address old = gov;
37 |         gov = pendingGov;
38 |         emit NewGov(old, pendingGov);
39 |     }
40 | 
41 |     function setEmergencyGov(address who) public governed {
42 |         emergency_gov = who;
43 |     } 
44 | 
